package io.github.jesterportfolio.hearth.gathering;

import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicLong;
import java.util.function.BooleanSupplier;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import static io.github.jesterportfolio.hearth.gathering.GatheringDungeonTest.*;

class GatheringVisitTest {
    static class Person implements GatheringVisit.Port{
        UUID id=UUID.randomUUID(),run;Object token=new Object();long generation=1;boolean valid=true,allowed=true,locked,held;int exits,saves;CompletableFuture<Void> saving=CompletableFuture.completedFuture(null);CompletableFuture<Boolean> moving=CompletableFuture.completedFuture(true);
        Person(UUID run){this.run=run;}public UUID player(){return id;}public Object session(){return token;}public UUID run(){return run;}public long worldGeneration(){return generation;}public boolean current(){return valid;}public boolean allowed(){return allowed;}public void freeze(boolean v){locked=v;}public CompletionStage<Void> save(){saves++;return saving;}public CompletionStage<Boolean> exit(BooleanSupplier valid){exits++;return moving.thenApply(ok->ok&&valid.getAsBoolean());}public void hold(){held=true;valid=false;}
    }
    @Test void exitWaitsForSaveAndDuplicateDoesNotStartSecondMovement(){var r=new Repo();var d=dungeon(r,new Port(),new AtomicLong());var p=new Person(r.row.run());var v=new GatheringVisit(Runnable::run,()->{});done(v.request(p,d,GatheringFacilities.Action.ENTER));p.saving=new CompletableFuture<>();var before=r.row;var exit=v.request(p,d,GatheringFacilities.Action.LEAVE);failed(v.request(p,d,GatheringFacilities.Action.LEAVE));assertTrue(p.locked);assertEquals(1,p.saves);assertEquals(0,p.exits);assertFalse(v.barrier(p.run()).toCompletableFuture().isDone());assertFalse(v.settled(p.run()));p.saving.complete(null);done(exit);done(v.barrier(p.run()));assertEquals(1,p.exits);assertEquals(0,d.occupants());assertTrue(r.row.emptyReset());assertFalse(before.emptyReset());assertFalse(p.locked);assertTrue(v.settled(p.run()));}
    @Test void failedSavePreservesMembershipAndOriginalStateAndHoldsOnlyThatRun(){var r=new Repo();var d=dungeon(r,new Port(),new AtomicLong());var p=new Person(r.row.run());var v=new GatheringVisit(Runnable::run,()->{});done(v.request(p,d,GatheringFacilities.Action.ENTER));var before=r.row;p.saving=CompletableFuture.failedFuture(new IllegalStateException("WRITE_FAILURE"));failed(v.request(p,d,GatheringFacilities.Action.LEAVE));assertEquals(before,r.row);assertEquals(1,d.occupants());assertEquals(0,p.exits);assertTrue(p.held);assertFalse(p.locked);assertFalse(v.settled(p.run()));failed(v.barrier(p.run()));var other=new Repo();var od=dungeon(other,new Port(),new AtomicLong());var op=new Person(other.row.run());done(v.request(op,od,GatheringFacilities.Action.ENTER));assertEquals(1,od.occupants());assertTrue(v.settled(op.run()));}
    @Test void oldWorldGenerationAndSessionCannotMoveAfterSave(){for(boolean replace:List.of(false,true)){var r=new Repo();var d=dungeon(r,new Port(),new AtomicLong());var p=new Person(r.row.run());var v=new GatheringVisit(Runnable::run,()->{});done(v.request(p,d,GatheringFacilities.Action.ENTER));p.saving=new CompletableFuture<>();var work=v.request(p,d,GatheringFacilities.Action.LEAVE);if(replace)p.valid=false;else p.generation++;p.saving.complete(null);failed(work);assertEquals(0,p.exits);assertEquals(1,d.occupants());assertTrue(p.held);}}
    @Test void failedMovementCannotRemoveLeaseOrMarkEmpty(){var r=new Repo();var d=dungeon(r,new Port(),new AtomicLong());var p=new Person(r.row.run());var v=new GatheringVisit(Runnable::run,()->{});done(v.request(p,d,GatheringFacilities.Action.ENTER));var before=r.row;p.moving=CompletableFuture.completedFuture(false);failed(v.request(p,d,GatheringFacilities.Action.LEAVE));assertTrue(p.held);assertEquals(before,r.row);assertEquals(1,d.occupants());}
    @Test void quitCancelsOnlyMatchingPendingOperationAndLateResultCannotRemoveNewSession(){var r=new Repo();var d=dungeon(r,new Port(),new AtomicLong());var p=new Person(r.row.run());var v=new GatheringVisit(Runnable::run,()->{});done(v.request(p,d,GatheringFacilities.Action.ENTER));p.saving=new CompletableFuture<>();var old=v.request(p,d,GatheringFacilities.Action.LEAVE);v.cancel(p.player(),new Object());assertFalse(old.toCompletableFuture().isDone());v.cancel(p.player(),p.session());failed(old);done(d.leave(p));p.valid=false;var next=new Person(p.run());next.id=p.id;done(v.request(next,d,GatheringFacilities.Action.ENTER));p.saving.complete(null);assertEquals(0,p.exits);assertFalse(next.held);assertTrue(d.canGather(next,d.snapshot().generation()));assertTrue(v.settled(p.run()));}
    @Test void resetDuringExitAndTimeoutNeverPermitLateMovement(){for(boolean reset:List.of(false,true)){var r=new Repo();var d=dungeon(r,new Port(),new AtomicLong());var p=new Person(r.row.run());var v=new GatheringVisit(Runnable::run,()->{});done(v.request(p,d,GatheringFacilities.Action.ENTER));p.saving=new CompletableFuture<>();var work=v.request(p,d,GatheringFacilities.Action.LEAVE);if(reset){done(d.reset(UUID.randomUUID()));p.saving.complete(null);}else p.saving.completeExceptionally(new TimeoutException("SAVE_DEADLINE"));failed(work);assertEquals(0,p.exits);assertTrue(p.held);assertFalse(p.locked);}}
    @Test void quitAfterMovementStillWaitsForExistingLeaveBookkeepingWithoutHoldingSuccess(){var r=new Repo();var delay=new boolean[1];var gate=new CompletableFuture<Void>();GatheringStore store=new GatheringStore(){public CompletionStage<State> read(){return r.read();}public CompletionStage<State> create(State value){return r.create(value);}public CompletionStage<State> save(State old,State next){return delay[0]&&next.emptyReset()?gate.thenCompose(v->r.save(old,next)):r.save(old,next);}};var d=new GatheringDungeon(content(),store,r.row,new Port(),Runnable::run,()->{},()->0);var p=new Person(r.row.run());var v=new GatheringVisit(Runnable::run,()->{});done(v.request(p,d,GatheringFacilities.Action.ENTER));delay[0]=true;var exit=v.request(p,d,GatheringFacilities.Action.LEAVE);assertEquals(1,p.exits);assertEquals(0,d.occupants());assertFalse(exit.toCompletableFuture().isDone());v.cancel(p.player(),p.session());p.valid=false;failed(exit);assertFalse(d.barrier().toCompletableFuture().isDone());gate.complete(null);done(d.barrier());done(v.barrier(p.run()));assertFalse(p.held);assertTrue(v.settled(p.run()));}
    @Test void closeRejectsNewRequestsAndPendingSaveCannotMove(){var r=new Repo();var d=dungeon(r,new Port(),new AtomicLong());var p=new Person(r.row.run());var v=new GatheringVisit(Runnable::run,()->{});done(v.request(p,d,GatheringFacilities.Action.ENTER));p.saving=new CompletableFuture<>();var work=v.request(p,d,GatheringFacilities.Action.LEAVE);v.close();p.saving.complete(null);failed(work);failed(v.request(p,d,GatheringFacilities.Action.ENTER));assertEquals(0,p.exits);assertFalse(p.locked);}
    @Test void wrongRunDeniedAndEntryFailureIsNotSuccess(){var r=new Repo();var boundary=new Port();var d=dungeon(r,boundary,new AtomicLong());var v=new GatheringVisit(Runnable::run,()->{});var wrong=new Person(UUID.randomUUID());failed(v.request(wrong,d,GatheringFacilities.Action.ENTER));assertEquals(0,boundary.enters);assertFalse(wrong.held);var p=new Person(r.row.run());boundary.entered=false;failed(v.request(p,d,GatheringFacilities.Action.ENTER));assertEquals(0,d.occupants());assertTrue(p.held);}
}
